// One variant per closure stored in this slot.
#[derive(Clone)]
pub enum ExpandCallback {
    NarrowTypeForInstance(ExpandCallbackNarrowTypeForInstance),
    NarrowTypeBasedOnClassPattern(ExpandCallbackNarrowTypeBasedOnClassPattern),
}

impl ExpandCallback {
    pub fn call(&self, type_: P<Type>) -> P<Type> {
        match self {
            ExpandCallback::NarrowTypeForInstance(c) => c.call(type_),
            ExpandCallback::NarrowTypeBasedOnClassPattern(c) => c.call(type_),
        }
    }
}

